"""Fifty CTB units reviewed against compiled text and applicable official acts."""
import copy,json,sys
from pathlib import Path
p=Path(sys.argv[1]);old=json.loads((p/'batch-03-existing.json').read_text());expected={r['unit']['unit_key']:r for r in old};rows={}
CTB='https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm'
L2020='https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/lei/l14071.htm'
L2021='https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14229.htm'
L2022='https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/lei/l14440.htm'
L2023='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14599.htm'
L2025='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15153.htm'
R969='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/resolucao9692022.pdf'
R996='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao9962023.pdf'
R1020='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao10202025.pdf'
D170='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/deliberacoes/deliberacao1702018.pdf'
ADC96='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/congresso/adc-96-mpv1.360.htm'
MP1360='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/mpv/mpv1360.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
STF='https://noticias.stf.jus.br/postsnoticias/supremo-julga-inconstitucional-norma-do-ctb-que-permite-ao-contran-criar-sancoes-para-infracoes-de-transito/'
def add(n,case,variation,q1,q2,term,meaning,**patch):
 key='art-'+str(n);e=copy.deepcopy(expected[key]['explanation']);data={k:e[k] for k in ['simples','pontos','atencao','exemplo','prova','termos','remissoes']}
 data.update(exemplo=case+' Variação: '+variation,prova=[q1,q2],termos=[dict(termo=term,significado=meaning)])
 data['pontos']+=patch.pop('extra_points',[]);data['atencao']+=patch.pop('notes',[]);data['remissoes']=list(dict.fromkeys([CTB,*data['remissoes'],*patch.pop('sources',[])]));data.update(patch);rows[key]=data
add(93,'Um projeto de centro comercial capaz de atrair trânsito tem estacionamento, mas não anuência do órgão com circunscrição. Resposta: o estacionamento não supre a anuência prévia.', 'A aprovação também exige indicar vias de acesso adequadas; não basta obter anuência e omitir essas informações.', 'Área de estacionamento dispensa a anuência do órgão de trânsito? Não. O artigo reúne anuência prévia, área de estacionamento e indicação de acessos adequados.', 'O artigo exige anuência apenas depois que o prédio estiver funcionando? Não. A exigência incide na aprovação do projeto que possa transformar-se em polo atrativo.', 'Polo atrativo','Edificação capaz de gerar demanda de circulação, examinada ainda na fase do projeto.',notes=['Não reduzir o controle à edificação já aberta; a aptidão do projeto para atrair trânsito é relevante.'])
add(94,'Uma obstrução na calçada não pode ser removida de imediato. Resposta: deve ser devida e imediatamente sinalizada, também para proteger pedestres.', 'O morador quer instalar lombada por conta própria: a exceção exige caso definido pelo órgão competente e padrões do Contran.', 'O dever de sinalizar obstáculo atinge apenas a pista de veículos? Não. O caput inclui via e calçada e protege veículos e pedestres.', 'Todo redutor ondulado é absolutamente proibido sem exceção? Não. O parágrafo admite casos especiais definidos pelo órgão competente, nos padrões e critérios do Contran.', 'Ondulação transversal','Redutor admitido apenas no regime excepcional e técnico pertinente.',notes=['Não ensinar lombada totalmente livre nem proibição sem a exceção legal; não inventar dimensões regulamentares neste artigo.'])
add(95,'Uma interdição programada ocorrerá em dois dias. Resposta: salvo emergência, a autoridade deve avisar a comunidade com 48 horas de antecedência e indicar caminhos alternativos.', 'A empresa executora obtém permissão, mas deixa a obra sem sinalização: a obrigação de sinalizar continua sendo do responsável pela execução ou manutenção.', 'A autoridade é sempre a responsável direta pela sinalização da obra? Não. O §1º atribui a obrigação ao responsável pela execução ou manutenção da obra ou evento.', 'A multa diária de 50% usa todo o salário mensal do servidor como base? Não. O §4º usa o DIA de vencimento ou remuneração devida enquanto persistir a irregularidade, não metade automática do salário mensal.', 'Interdição avisada','Comunicação prévia de fechamento e rota alternativa, com ressalva de emergência.',extra_points=['§3º: multa textual R$ 81,35 a R$ 488,10; diária a partir do prazo final concedido até regularização; não elimina consequências civis e penais.','§4º: servidor, multa diária de 50% do DIA de vencimento/remuneração; integra também arts. 93 e 94.'],notes=['Distinguir permissão prévia, obrigação de sinalizar, aviso comunitário e sanções próprias.'])
add(96,'Uma motocicleta é configurada para transporte de carga. Resposta: pode integrar a espécie de carga; não classificar toda motocicleta automaticamente como passageiros.', 'A categoria aluguel é outro eixo de classificação, distinto de tração automotora ou espécie de carga.', 'Tração, espécie e categoria são critérios equivalentes? Não. O artigo separa três eixos; um veículo deve ser enquadrado em cada um conforme suas características e uso.', 'A classificação elétrica continua como alínea b vigente do inciso I? Não. A Lei 14.599/2023 revogou essa alínea; não recuperar o rol antigo como atual.', 'Eixos de classificação','Critérios independentes: tração, espécie e categoria do veículo.',simples='O art. 96 separa tração, espécie e categoria. Categoria inclui oficial, representação diplomática/consular/internacional, particular, aluguel e aprendizagem. A espécie pode ser passageiros, carga, misto, competição, tração, especial ou coleção. Um mesmo tipo, como motocicleta, aparece em mais de uma espécie. A alínea elétrica da classificação por tração foi revogada em 2023.',pontos=['TRAÇÃO: automotor, propulsão humana, tração animal, reboque/semirreboque; alínea b REVOGADA.','ESPÉCIE não é sinônimo de CATEGORIA.','Motocicleta aparece em passageiros, carga e especial, conforme enquadramento.','Lei 14.599/2023 explicitou tipos da espécie especial; não ensinar rol antigo incompleto.'],sources=[L2023])
add(97,'Um fabricante pretende cadastrar veículo com configuração inédita. Resposta: condições essenciais de registro, licenciamento e circulação são estabelecidas pelo Contran em função das aplicações.', 'A autoridade executiva pratica atos de registro, mas não substitui por vontade própria os padrões normativos nacionais.', 'O fabricante determina sozinho as condições legais de circulação? Não. O artigo atribui ao Contran as características, especificações e condições essenciais.', 'Especificações básicas são irrelevantes para o licenciamento? Não. O caput as relaciona expressamente às condições para registro, licenciamento e circulação.', 'Especificação básica','Requisito técnico nacional ligado à aplicação do veículo e à sua regularidade.',notes=['Separar função normativa do Contran e atos administrativos dos órgãos executivos.'])
add(98,'Uma oficina modifica características de fábrica com autorização prévia. Resposta: autorização não dispensa limites de emissão e ruído; executor e proprietário respondem pelo cumprimento.', 'Alterar conjunto roda/pneu de utilitário jipe depende das restrições do fabricante e exigências do Contran, não autorização genérica para qualquer veículo.', 'Basta chamar a mudança de melhoria para dispensar autorização? Não. O caput exige prévia autorização para fazer ou ordenar modificação das características de fábrica.', 'Só o proprietário responde pelos limites ambientais da conversão? Não. O §1º também atribui responsabilidade à entidade executora das modificações.', 'Modificação autorizada','Mudança sujeita a controle prévio e demais requisitos de segurança e ambientais.',notes=['Lei 14.071/2020: distinguir alteração de características, emissões/ruído e hipótese específica de utilitário jipe.'],sources=[L2020])
add(99,'Na pesagem, o veículo supera o limite nominal, mas não o limite acrescido da tolerância aplicável. Resposta: o §4º impede autuação por pesagem antes de ultrapassar esse conjunto.', 'O limite técnico por eixo precisa constar em lugar visível e no Renavam; a tolerância não autoriza desrespeitar capacidades técnicas do fabricante.', 'Basta superar qualquer limite nominal para autuar na pesagem? Não. O §4º exige ultrapassar os limites fixados acrescidos da respectiva tolerância.', 'O artigo fixa um único percentual universal para toda modalidade de aferição? Não. Diferencia aferição por equipamento/documento e remete à regulamentação; não inventar percentual para todo caso.', 'Tolerância de aferição','Margem do regime aplicável à pesagem, distinta de autorização para excesso habitual.',extra_points=['§4º e §5º incluídos pela Lei 14.229/2021, com regime de vigência próprio já transcorrido.','Limite técnico por eixo: informação visível na estrutura E no Renavam.'],notes=['Não recuperar automaticamente a regra transitória de peso da Lei 7.408, cujo prazo foi limitado, como fórmula atual universal.'],sources=[L2021])
add(100,'O fabricante fixa lotação do ônibus e capacidade de tração da unidade tratora. Resposta: ambas são limites pertinentes; cumprir o peso não libera excesso de passageiros.', 'O §3º permite até 15 m em configuração de chassi 8x2, sem transformar toda configuração em veículo de 15 m autorizado.', 'Pneus extralargos são proibidos para todo coletivo? Não. O §1º permite nos coletivos; o §2º remete os demais veículos à regulamentação do Contran.', 'A capacidade de tração pode ser ultrapassada porque o peso por eixo está regular? Não. O caput protege limites distintos, inclusive a capacidade máxima de tração.', 'Capacidade de tração','Limite da unidade tratora, diferente de lotação ou peso por eixo.',notes=['Não estender o permissivo de 15 m a qualquer chassi; o §3º especifica configuração 8x2.'])
add(101,'Uma composição de carga excedente recebe AET por período com prazo certo. Resposta: é modalidade admitida; a autorização não precisa limitar-se invariavelmente a uma viagem.', 'Mesmo autorizada, a composição causa dano à via: o §2º não exonera o beneficiário dessa responsabilidade.', 'Toda AET tem prazo legal universal de seis meses? Não. Seis meses é hipótese dos guindastes do §3º; o caput admite prazo certo por viagem ou período.', 'A AET dispensa toda medida de segurança e responsabilidade por dano? Não. São mantidas medidas necessárias e responsabilidade por dano à via ou a terceiros.', 'AET','Autorização especial de trânsito, com prazo e segurança conforme o caso.',exemplo='Uma composição de carga excedente recebe AET por período com prazo certo. Resposta: é modalidade admitida; a autorização não precisa limitar-se invariavelmente a uma viagem. Variação: mesmo autorizada, causa dano à via; o §2º não exonera o beneficiário.',extra_points=['Guindastes: hipótese de seis meses no §3º.','§4º: mínimos específicos para tráfego exclusivamente em via rural não pavimentada, com caráter regional diferenciado.'],notes=['Não afirmar escolta obrigatória em todo caso apenas pelo art. 101; conferir regulamentação e características da operação.'],sources=[L2021])
add(102,'Um caminhão transporta carga que pode derramar na pista. Resposta: precisa estar equipado de forma a impedir derramamento, conforme natureza e regras de proteção da carga.', 'A autorização de transporte não libera perder material na via; cumprir um documento não substitui proteção adequada.', 'O dever de evitar derramamento vale apenas para viagem longa? Não. O artigo não cria dispensa por curta distância quando o veículo transita.', 'O art. 102 fixa uma cobertura idêntica para toda carga? Não. O parágrafo remete requisitos mínimos e forma de proteção ao Contran conforme a natureza da carga.', 'Proteção da carga','Medida técnica que evita derramamento e depende da natureza transportada.',notes=['Não transformar um exemplo de lona em exigência universal para todas as cargas; integrar o regulamento adequado.'])
add(103,'Pretende-se experimentar condição de circulação não prevista ordinariamente. Resposta: a autorização do §3º cabe ao Contran, em caráter experimental e por período prefixado.', 'No art. 80, §2º, a autorização experimental de sinalização cabe ao máximo executivo federal; não copiar a mesma competência para ambos.', 'A autorização experimental do art. 103 cabe ao órgão municipal por livre escolha? Não. O §3º atribui a possibilidade ao Contran e exige duração prefixada.', 'Certificado de segurança elimina o dever de manter resultados dos ensaios disponíveis? Não. O §2º exige disponibilidade a qualquer tempo e procedimentos de comprovação definidos pelo Contran.', 'Experimento veicular','Circulação excepcional autorizada pelo Contran com duração definida.',notes=['§3º incluído pela Lei 14.599/2023. Distinguir competência experimental de veículos e a de sinalização do art. 80.'],sources=[L2023])
add(104,'Um carro novo particular para até sete passageiros sofre sinistro com dano de média monta. Resposta: perde o pressuposto de isenção trienal, que exige ausência desse evento e características originais.', 'O candidato presume inspeção nacional anual automática de toda frota: não concluir isso; o índice oficial mantém a Resolução 716/2017 suspensa por tempo indeterminado pela Deliberação 170/2018.', 'A isenção de três anos independe de manter características originais? Não. O §6º condiciona o benefício à originalidade e à ausência de sinistro com danos de média ou grande monta.', 'A suspensão da Resolução 716 elimina todas as inspeções previstas no CTB? Não. Não revoga o art. 104 nem dispensa inspeções específicas, como escolares; não presumir calendário nacional universal ativo.', 'Inspeção específica','Avaliação segundo regime pertinente, distinta de supor implantação geral uniforme.',simples='O art. 104 prevê inspeção de segurança sob normas do Contran e de emissões/ruído sob normas do Conama. Retenção incide em reprovação. Isenções textuais de três anos (particular novo, até sete passageiros) ou dois anos (demais novos) dependem de características originais e ausência de sinistro de média/grande monta. ALERTA: o programa da Resolução 716/2017 está suspenso por tempo indeterminado pela Deliberação 170/2018 no índice consultado; não ensinar periodicidade geral nacional como se estivesse plenamente implantada. Inspeções específicas continuam com disciplina própria.',atencao=['Não confundir previsão legal, isenção condicionada e implantação regulamentar.','Contran: segurança; Conama: gases e ruído.','Deliberação 170/2018 suspende Resolução 716/2017; índice oficial de 13/10/2026 ainda registra a suspensão. Isso não elimina inspeção semestral escolar do art. 136.'],sources=[D170])
add(105,'Um coletivo tem onze lugares, enquanto um veículo de carga tem PBT exatamente 4.536 kg. Resposta: o inciso II inclui mais de dez lugares e PBT SUPERIOR a 4.536 kg; não trocar limites por igual ou superior.', 'O inciso VIII de DRL precisa ser integrado ao cronograma e à regulamentação, sem obrigar adaptar toda frota antiga apenas por leitura isolada.', 'O rol do art. 105 esgota todo equipamento obrigatório? Não. O caput permite outros estabelecidos pelo Contran e o §1º remete especificações técnicas.', 'A exceção textual de cinto para percurso em pé dispensa todo coletivo indistintamente? Não. O inciso I traz recorte de veículo destinado a percurso em que é permitido viajar em pé, integrado à regulamentação.', 'Equipamento por categoria','Obrigação cujo alcance depende do tipo de veículo e das normas técnicas aplicáveis.',notes=['Não transformar airbag/DRL em obrigação retroativa universal da frota sem conferir cronograma, projeto e regulamentação.','§6º: a exigência do inciso VII não se aplica aos veículos destinados à exportação; não dispensa geral de segurança.'])
add(106,'Veículo artesanal precisa ser registrado e licenciado. Resposta: exige certificado por instituição técnica credenciada em metrologia legal, conforme norma do Contran.', 'A blindagem tem ressalva de não exigir outro documento/autorização para registro ou licenciamento; isso não vira dispensa universal de segurança, modificação regular ou outras regras aplicáveis.', 'Qualquer oficina não credenciada pode emitir o certificado exigido? Não. O caput exige instituição técnica credenciada por órgão ou entidade de metrologia legal.', 'O parágrafo de blindagem libera toda obrigação de segurança do veículo? Não. Delimita documento/autorização adicional para registro ou licenciamento, sem revogar o restante do CTB.', 'Certificado técnico','Documento de instituição credenciada para o recorte de registro e licenciamento.',atencao=['A expressão nenhum outro documento ou autorização no parágrafo não deve ser ampliada para dispensa de todo requisito do veículo ou de qualquer regime externo.','Distinguir certificado deste artigo e o emitido pelos sujeitos do art. 103.'],sources=[L2020])
add(107,'Um táxi preenche requisitos do CTB, mas descumpre higiene exigida pelo poder competente. Resposta: as condições adicionais de segurança, higiene e conforto também se aplicam.', 'Cumprir condição local não dispensa o veículo das exigências nacionais do CTB.', 'Exigência local de higiene substitui integralmente o CTB? Não. O caput usa além das exigências previstas no código, indicando integração.', 'A competência adicional se limita a conceder serviço coletivo? Não. O artigo inclui transporte individual ou coletivo e autorizar, permitir ou conceder a exploração.', 'Requisito adicional','Condição do poder competente que se soma às exigências nacionais.',notes=['Não confundir regulamentação adicional válida com liberdade para contrariar normas federais.'])
add(109,'Um veículo destinado a passageiros transportará carga. Resposta: é preciso obedecer às normas do Contran, não presumir autorização sem condições.', 'A regra não proíbe absolutamente toda carga nesse tipo de veículo; admite realização no regime normativo pertinente.', 'O artigo libera carga em veículo de passageiros por decisão do motorista? Não. Só permite realização conforme as normas estabelecidas pelo Contran.', 'A norma significa proibição absoluta sem possibilidade regulamentar? Não. O texto condiciona a atividade à regulamentação, em vez de excluí-la em toda hipótese.', 'Carga condicionada','Transporte compatível com o regulamento aplicável, sem autorização irrestrita.',notes=['Não inserir limite de quantidade ou exigência de compartimento específico sem validar a norma pertinente.'])
add(110,'Um automóvel foi alterado para competição e pretende circular em via pública. Resposta: necessita licença especial da autoridade, com itinerário e horário fixados.', 'A licença de circulação não substitui automaticamente a permissão de uma competição em via aberta, regida pelo art. 67.', 'A licença especial vale para qualquer rota e horário? Não. O caput exige itinerário e horário fixados, não circulação irrestrita.', 'Art. 110 e art. 67 concedem a mesma autorização para todo caso? Não. Um trata de veículo alterado para competição; outro, de realização de provas e ensaios na via.', 'Licença especial','Permissão de circulação de veículo alterado, delimitada por percurso e horário.',notes=['Não confundir licença de circulação, autorização de modificação e permissão para competição.'])
add(111,'Um veículo em movimento usa persianas fechadas e não tem retrovisores dos dois lados. Resposta: não se enquadra na exceção do inciso II.', 'Ter retrovisores dos dois lados não permite película que comprometa a segurança; o inciso III tem regra e regulamentação próprias.', 'Retrovisores de ambos os lados tornam qualquer película automaticamente regular? Não. A exceção do inciso II não elimina a restrição de segurança e regulamentação do inciso III.', 'O inciso I vetado institui atualmente uma proibição autônoma? Não. Vetado não equivale a norma vigente; não afirmar que foi lei válida depois suprimida apenas pela marcação.', 'Área envidraçada','Superfície sujeita a regras de visibilidade e segurança, com exceções delimitadas.',atencao=['Inciso I: VETADO, sem comando vigente. Não confundir veto com revogação posterior.','Inciso II: exceção de retrovisores nos dois lados; inciso III e parágrafo: segurança e regulamentação, sem dispensa universal.','Não ensinar um percentual único de película para todos os vidros sem conferir resolução e posição do vidro.'])
add(113,'Uma falha de projeto gera dano ao usuário e ao ambiente. Resposta: o artigo prevê responsabilidade civil e criminal dos sujeitos indicados, conforme os requisitos de cada regime.', 'A menção a responsabilidade criminal não condena automaticamente toda pessoa ligada à empresa sem examinar conduta, tipicidade e imputação.', 'O artigo protege apenas quem comprou o veículo? Não. Abrange usuários, terceiros e meio ambiente diante de falhas de projeto ou qualidade.', 'Responsabilidade criminal prevista dispensa provar seus pressupostos no caso? Não. O artigo não autoriza condenação penal automática por qualquer dano ou vínculo empresarial.', 'Responsabilidade delimitada','Consequências civis e criminais nos seus respectivos requisitos, sem condenação automática.',notes=['Distinguir responsabilidade civil e penal; não criar tipo penal ou culpa automática apenas pelo dano.'])
add(114,'Um chassi precisa de regravação. Resposta: exigir autorização prévia, estabelecimento credenciado e prova de propriedade, mantendo identificação anterior e ano de fabricação.', 'Regravar para atribuir ano mais recente não é permitido pelo regime legal.', 'A regravação permite alterar o ano de fabricação? Não. Os §§1º/2º preservam o ano e a identificação anterior, não uma nova identidade arbitrária.', 'Apenas prova de propriedade dispensa autorização e credenciamento? Não. O §2º reúne esses requisitos, e o §3º impede alteração sem prévia permissão.', 'Regravação regular','Reprodução autorizada da identificação anterior por estabelecimento credenciado.',notes=['Não transformar autorização de regravação em permissão para mudar identidade do veículo.'])
add(115,'Um veículo usa PIV com QR Code no modelo regulamentado. Resposta: a Resolução 969/2022 trata o código como lacre eletrônico que substitui o lacre do caput, integrado ao §9º.', 'Uma placa antiga continua sujeita ao seu regime pertinente; a dispensa de lacre físico da PIV não libera identificação defeituosa de todo modelo.', 'Toda placa traseira exige lacre físico sem exceção? Não. O §9º admite dispensa com tecnologia de identificação e a Resolução 969, art. 3º, estabelece lacre eletrônico por QR Code.', 'O registro agrícola do §4º-A exige pagamento obrigatório no Detran? Não. O recorte atual prevê registro único sem ônus no cadastro específico do Ministério da Agricultura e Pecuária.', 'Lacre eletrônico','QR Code de identificação no regime da PIV, distinto de ausência de controle da placa.',simples='O veículo tem placas conforme o modelo do Contran, com exceções, como dispensa dianteira para duas ou três rodas e regime de veículo bélico. O §9º permite dispensa do lacre físico por tecnologia de identificação: na PIV, a Resolução 969/2022 prevê QR Code como lacre eletrônico. Registro de máquinas de construção e de máquinas agrícolas tem recortes próprios; não exigir licenciamento/emplacamento universal dessas hipóteses. Placas especiais e particulares dependem dos pressupostos específicos.',pontos=['Duas/três rodas: dispensa de placa dianteira no §6º; não generalizar para todos os automotores.','Caracteres individualizados até baixa, vedado reaproveitamento.','§9º + Resolução 969, art. 3º: lacre eletrônico por QR Code substitui lacre físico no modelo PIV.','§4º: máquinas de construção/pavimentação na via pública têm registro, dispensados licenciamento e emplacamento.','§4º-A: máquinas agrícolas, registro único gratuito no Ministério da Agricultura e Pecuária.','§7º: placa especial temporária exige autorização específica fundamentada e comunicação; não privilégio automático de toda autoridade.'],atencao=['Não repetir placa sempre lacrada fisicamente sem a exceção tecnológica.','Não confundir §7º (proteção temporária de membros com atribuição criminal) e art. 116 (serviço policial reservado).','§10: livre passagem exige meios técnicos de identificação; não significa anonimato ou dispensa de pagamento de pedágio.'],sources=[R969,L2023])
add(116,'Um órgão de segurança usa veículo sob sua posse, estritamente em serviço policial reservado. Resposta: pode requerer placa particular no recorte atual, que não se limita à propriedade.', 'Um veículo oficial em atividade administrativa comum não recebe a mesma permissão apenas por integrar a frota policial.', 'O artigo exige sempre propriedade do órgão de segurança? Não. A redação de 2023 também inclui veículos sob posse desses órgãos, com as demais condições.', 'A placa é desvinculada de qualquer órgão para manter anonimato administrativo total? Não. O parágrafo determina concessão por solicitação e vínculo ao órgão de segurança requerente.', 'Serviço reservado','Uso policial estritamente delimitado que fundamenta a placa particular.',notes=['Lei 14.599/2023 atualizou propriedade/posse e vinculação; não ampliar a toda atividade oficial.'],sources=[L2023])
add(117,'Um coletivo de passageiros não exibe sua lotação em local facilmente visível. Resposta: a inscrição é exigida junto aos dados de peso/capacidade pertinentes.', 'Mostrar dados técnicos não permite usar o veículo em desacordo com a classificação.', 'A inscrição pode ficar em local inacessível à observação? Não. O caput exige local facilmente visível para veículos de carga e coletivos de passageiros.', 'Tara e lotação designam exatamente a mesma capacidade? Não. Tara é dado de peso do veículo; lotação e capacidades de peso/tração são grandezas distintas.', 'Tara','Peso próprio do veículo no conceito técnico, diferente da carga transportada ou lotação.',notes=['Não trocar PBT, PBTC e CMT nem deduzir capacidade por sigla sem consultar definição correspondente.'])
add(118,'Um veículo estrangeiro circula no Brasil numa operação entre países com acordo ratificado. Resposta: integrar CTB e convenções/acordos ratificados pertinentes.', 'Uma referência a acordo ainda não ratificado não basta para aplicar automaticamente suas regras como regime vigente.', 'A origem estrangeira exclui a aplicação do CTB? Não. O artigo prevê o CTB integrado às convenções e acordos internacionais ratificados.', 'Qualquer acordo anunciado, mesmo sem ratificação, substitui as regras? Não. O caput exige convenções e acordos ratificados, sem dispensa universal pela nacionalidade do veículo.', 'Acordo ratificado','Instrumento internacional incorporado no regime pertinente, não mera notícia de negociação.',notes=['Não afirmar que todo veículo de país vizinho está dispensado de documentação ou normas brasileiras.'])
add(119,'Um veículo licenciado no exterior causou dano e recebeu infração no Brasil. Resposta: a saída depende de pagamento ou depósito judicial/administrativo dos valores pertinentes, conforme §1º.', 'Se saiu sem regularização e volta, pode ser retido até regularizar; não substituir retenção por antiga penalidade de apreensão.', 'O artigo só permite quitação definitiva em dinheiro para a saída? Não. O §1º admite pagamento OU depósito judicial ou administrativo, sem eliminar demais requisitos.', 'A comunicação ao Renavam só alcança entrada definitiva? Não. O caput inclui entrada e saída temporária ou definitiva comunicadas pelos órgãos indicados.', 'Depósito admitido','Alternativa judicial ou administrativa prevista para os valores pertinentes à saída.',notes=['Distinguir veículo licenciado no exterior e pessoa estrangeira; o recorte é do veículo.','§2º: retenção até regularização, não antiga penalidade de apreensão.'])
add(120,'O proprietário reside em um município e registra o veículo perante o órgão executivo estadual competente. Resposta: município de domicílio/residência e órgão estadual/distrital são referências distintas.', 'Veículo de serviço reservado do art. 116 tem exceção à identificação pintada nas portas; não aplicar pintura indistintamente a todo oficial.', 'O órgão municipal é sempre quem realiza o registro do caput? Não. O artigo aponta órgão executivo do Estado ou DF, no município pertinente ao proprietário.', 'Todo veículo oficial, inclusive os do art. 116, precisa da mesma pintura? Não. O §1º excepciona veículos de representação e os previstos no art. 116.', 'Local e órgão de registro','Referências territorial e administrativa que não se confundem.',notes=['§2º: veículo bélico fora desta regra. Não omitir exceções de representação e serviço reservado.'],sources=[L2023])
add(121,'Depois do registro, o proprietário escolhe o meio digital do CRV conforme padrões regulamentares. Resposta: há previsão física e/ou digital, com proteção contra falsificação e adulteração.', 'Ter CRV não prova sozinho o licenciamento anual atual; CRLV tem disciplina própria.', 'O art. 121 obriga documento apenas em papel? Não. A redação da Lei 14.071/2020 admite físico e/ou digital, à escolha do proprietário.', 'CRV e certificado anual são a mesma obrigação para qualquer finalidade? Não. O CRV resulta do registro; licenciamento anual e seu certificado são tratados nos arts. 130/131.', 'CRV','Certificado do registro do veículo, distinto do licenciamento anual.',notes=['Preservar o e/ou da redação legal; não reduzir registro e licenciamento a ato único permanente.'],sources=[L2020])
add(122,'O requerente apresenta documento equivalente à nota fiscal expedido por autoridade competente. Resposta: o inciso I admite essa alternativa, não exige invariavelmente nota fiscal comercial.', 'Importação pela hipótese diplomática do inciso II tem documento do Ministério das Relações Exteriores, não obrigação idêntica para todo proprietário.', 'Só nota fiscal é juridicamente admitida pelo inciso I? Não. Também admite documento equivalente expedido por autoridade competente.', 'O documento do Ministério das Relações Exteriores é exigido em todo registro nacional? Não. O inciso II condiciona-o à importação pelos sujeitos diplomáticos/consulares/internacionais descritos.', 'Documento equivalente','Alternativa expressa à nota fiscal, expedida por autoridade competente.',atencao=['Não ensinar nota fiscal sem a alternativa equivalente; não generalizar exigência diplomática.'])
add(123,'O comprador providencia novo CRV em trinta dias após transferência. Resposta: é seu prazo; mudança para outro município e alteração de característica/categoria têm providências imediatas.', 'Mudar de endereço dentro do mesmo município exige comunicação em trinta dias e aguardar novo licenciamento para alterar o certificado anual, situação diferente de mudar de município.', 'Toda mudança de endereço exige novo CRV imediato? Não. O §2º distingue mudança dentro do mesmo município da hipótese do inciso II.', 'Transferência eletrônica exige sempre assinatura qualificada, excluindo a avançada? Não. O §4º admite qualificada ou avançada; a avançada depende de plataforma homologada e normas pertinentes.', 'Transferência eletrônica','Procedimento digital com assinaturas e plataforma nos requisitos legais, sem assinatura informal universal.',extra_points=['Lei 15.153/2025, publicada em 27/6/2025, acrescentou §4º; distinguir data da lei, publicação e conferência de 13/10/2026.','§4º, II: contrato digital assinado por comprador/vendedor perante máximo executivo federal tem validade nacional e aceitação obrigatória.','§4º, III: plataforma de assinatura avançada homologada; V: vistoria eletrônica a critério do órgão estadual/distrital, não direito automático de dispensar vistoria.'],notes=['O inciso IV permanece vetado; não gerar obrigação fictícia. Transferência eletrônica não elimina por si prazos ou outros requisitos.'],sources=[L2025])
add(124,'Veículo é transferido por leilão de recolhido em depósito e possui débito anterior. Resposta: o parágrafo dispensa o requisito de quitação do inciso VIII nesse recorte e remete cobrança ao antigo proprietário.', 'Certidão negativa de roubo/furto pode ser substituída por informação do Renavam; não torná-la papel obrigatório em toda hipótese.', 'A dispensa do parágrafo anula a dívida anterior? Não. Dispensa o inciso VIII para a transferência especificada, mas determina cobrança dos débitos do proprietário anterior.', 'Toda aquisição particular comum recebe a mesma dispensa de débitos? Não. O parágrafo enumera apreensão/confisco judicial, leilão de recolhido em depósito e doação a órgãos públicos.', 'Dispensa para transferência','Exceção específica de requisito, distinta de perdão da dívida.',extra_points=['ADI 2998/STF manteve constitucional o inciso VIII; não ensinar afastamento universal da quitação.','Parágrafo atual: Lei 14.440/2022; dispensa só do inciso VIII, não de todo documento.','Inciso XI: inspeções quando for o caso; integrar regulamentação e suspensão do programa geral, sem calendário universal.'],notes=['Não usar apreensão judicial do parágrafo como restauração da antiga penalidade administrativa de apreensão.'],sources=[L2022,STF,D170])
add(125,'Pessoa física importa veículo. Resposta: as informações originárias são prestadas pelo órgão alfandegário; se importação por pessoa jurídica, o responsável é o importador.', 'No veículo nacional, fabricante/montadora informa antes da comercialização; depois do registro o órgão comunica ao Renavam.', 'O mesmo sujeito presta dados originários em toda importação? Não. O inciso II aponta órgão alfandegário para pessoa física e o III, importador para pessoa jurídica.', 'O órgão que registra dispensa comunicação ao Renavam porque recebeu os dados? Não. O parágrafo exige comunicar tão logo o veículo seja registrado.', 'Pré-cadastro originário','Informações fornecidas pelo sujeito legal adequado antes ou em função do registro.',notes=['Distinguir dados do fabricante/alfândega/importador e comunicação posterior pelo órgão registrador.'])
add(126,'Veículo destinado à desmontagem tem débitos fiscais e multas ambientais. Resposta: isso não impede a baixa, conforme §2º, sem extinguir automaticamente as dívidas.', 'Seguradora ou adquirente que sucede ao proprietário assume o dever; não afirmar que toda perda econômica configura sempre veículo tecnicamente irrecuperável.', 'A baixa pode ser condicionada à quitação de toda multa? Não. O §2º permite baixa mesmo com débitos fiscais e multas de trânsito ou ambientais vinculadas.', 'Remontar sobre o mesmo chassi para preservar o registro anterior é permitido? Não. O caput veda essa utilização para veículo irrecuperável ou destinado à desmontagem.', 'Baixa do registro','Encerramento registral do veículo no regime legal, distinto de extinção de dívidas.',notes=['§§1º/2º incluídos pela Lei 14.440/2022. Não equiparar toda perda total econômica à classificação técnica de irrecuperável sem análise.'],sources=[L2022])
add(127,'O órgão vai baixar o registro de um veículo. Resposta: consulta antes o cadastro do Renavam e comunica a baixa imediatamente depois.', 'A consulta não pode ser trocada por comunicação tardia como se as duas etapas fossem uma só.', 'Consultar o cadastro depois da baixa satisfaz a exigência de consulta prévia? Não. O caput condiciona a baixa à consulta anterior do Renavam.', 'A comunicação depois da baixa pode ser livremente postergada? Não. O parágrafo exige comunicação de imediato ao Renavam, sem prazo arbitrário criado neste artigo.', 'Sequência registral','Consulta anterior e comunicação imediata posterior à baixa.',notes=['Não inventar prazo de trinta dias para a comunicação deste artigo.'])
add(128,'Há débitos vinculados ao veículo numa transferência privada comum. Resposta: a regra impede novo CRV; a ADI 2998 manteve o caput constitucional.', 'A aquisição enquadrada na exceção do art. 124, parágrafo, não deve receber a regra geral sem essa integração.', 'A ADI 2998 retirou toda exigência de quitação para novo CRV? Não. O STF manteve este caput constitucional, distinguindo-o da autorização para o Contran criar sanções.', 'A regra autoriza cobrar qualquer lançamento irregular sem defesa? Não. Examinar exigibilidade, regular procedimento e exceções aplicáveis; constitucionalidade não dispensa garantias.', 'Débito vinculado','Obrigação relativa ao veículo no regime pertinente, com exigibilidade e exceções próprias.',simples='A regra geral impede novo CRV com débitos fiscais e multas de trânsito/ambientais vinculados, independentemente de quem cometeu a infração. A ADI 2998 manteve o caput constitucional. Integrar exceções específicas, especialmente art. 124, parágrafo, e garantias do procedimento de cobrança; não converter o texto em exigibilidade automática de qualquer lançamento.',atencao=['STF, ADI 2998, notícia oficial de 10/4/2019: caput constitucional; a decisão sobre sanções do Contran não anulou esta regra.','Constitucionalidade não elimina defesa nem exceções legais; não restaurar exigência universal de quitação para baixa do art. 126.'],sources=[STF])
add(129,'O município regulamenta registro de carroças e veículos de propulsão humana de residentes. Resposta: integra a atribuição municipal do artigo.', 'Ciclomotor não está incluído por ter pequena potência: não reinseri-lo no rol retirado em 2015.', 'O texto atual entrega registro de todo ciclomotor ao município? Não. Abrange propulsão humana e tração animal; ciclomotores têm regime próprio.', 'A legislação de qualquer município é escolhida livremente pelo proprietário? Não. O artigo aponta legislação municipal do domicílio ou residência do proprietário.', 'Regime municipal','Regulamentação de propulsão humana e tração animal vinculada ao domicílio/residência.',notes=['Lei 13.154/2015 retirou ciclomotores deste recorte; bicicleta elétrica e equiparados exigem também verificar art. 134-A e Resolução 996.'])
add('129-a','Um trator destinado a trabalho agrícola é registrado pelo Ministério da Agricultura e Pecuária mediante convênio. Resposta: a modalidade é admitida e o registro é sem ônus.', 'Máquina de construção não se torna agrícola só por puxar equipamento; conferir destinação e hipótese do art. 115.', 'O Ministério só pode registrar diretamente sem cooperação? Não. O artigo admite atuação direta ou mediante convênio, sem ônus para o registro previsto.', 'Todo aparelho automotor se submete a este cadastro por existir? Não. O caput delimita tratores e máquinas destinados a puxar maquinaria agrícola ou executar trabalho agrícola.', 'Cadastro agrícola','Registro especial gratuito de máquinas destinadas às atividades agrícolas especificadas.',notes=['Redação de 2023 identifica Ministério da Agricultura e Pecuária; não atribuir categoria indistinta a máquina de construção.'],sources=[L2023])
add('129-b','Uma garantia de financiamento é registrada por empresa especializada credenciada pelo executivo estadual. Resposta: observar Código Civil, proteção de dados e credenciamento no recorte atual.', 'O tratamento de dados para registro não autoriza exposição pública irrestrita de informações pessoais.', 'O banco pode substituir livremente o credenciamento com registro informal próprio? Não. O parágrafo prevê execução por registradora especializada credenciada pelo órgão estadual/distrital.', 'O art. 129-B ignora a LGPD porque se trata de veículo? Não. O caput remete expressamente à Lei Geral de Proteção de Dados Pessoais.', 'Gravame contratual','Garantia registrada no regime próprio, distinta de simples informação informal do credor.',notes=['Lei 14.599/2023 acrescentou parágrafo com remissão ao art. 79 da Lei 14.133; não confundir modalidade de credenciamento e dispensa universal de procedimento.'],sources=[L2023])
add(130,'O proprietário muda de residência durante o exercício com licenciamento de origem válido. Resposta: o §2º preserva a validade nesse exercício, não dispensa regularização futura.', 'Veículo de uso bélico tem a exceção do §1º; não exigir o regime anual deste artigo de modo universal.', 'O licenciamento é bienal pela regra do art. 130? Não. O caput exige licenciamento anual no órgão estadual ou distrital onde o veículo está registrado.', 'Mudança de domicílio invalida imediatamente todo licenciamento anterior? Não. O §2º mantém válido o de origem durante o exercício, com as demais obrigações pertinentes.', 'Licenciamento anual','Regularidade periódica, distinta do registro e da mudança de domicílio.',notes=['Redação de 2023; mudança de residência não é dispensa permanente de licenciamento.'],sources=[L2023])
add(131,'Recall comunicado de campanha realizada desde 1º/10/2019 não é atendido durante um ano. Resposta: informação deve constar do certificado e depois disso o §5º condiciona o licenciamento à comprovação de atendimento.', 'Há comprovada falta de peças: o §7º permite prorrogação excepcional pelo Contran, avaliada segurança, não decisão unilateral do proprietário.', 'Qualquer recall bloqueia automaticamente o licenciamento no mesmo dia do anúncio? Não. Integrar data de campanha, um ano da comunicação, inclusão da informação e a eventual prorrogação excepcional.', 'Inspeção do §3º prova calendário nacional anual implantado para toda frota? Não. Integrar art. 104, regimes específicos e suspensão do programa da Resolução 716 pela Deliberação 170.', 'Recall','Chamamento para substituição/reparo, com marcos e consequências próprias no licenciamento.',simples='O certificado anual se vincula ao CRV, em meio físico e/ou digital. Primeiro licenciamento junto ao registro; débitos exigíveis e inspeções pertinentes integram o regime. No recall, campanhas realizadas desde 1º/10/2019 não atendidas em um ano da comunicação passam ao certificado; após inclusão, comprovar atendimento para licenciar. O Contran pode excepcionalmente prorrogar essa exigência por falta comprovada de peças ou escalonamento, considerando segurança. Não supor inspeção geral nacional implantada pela mera remissão ao art. 104.',pontos=['Primeiro licenciamento SIMULTÂNEO ao registro.','ADI 2998: §2º constitucional; não confundir com autorização de criar sanção.','Recall: campanha desde 1º/10/2019 → um ano da comunicação → informação no certificado → requisito do §5º.','§6º: dados de campanhas anteriores dependem do regulamento.','§7º: prorrogação EXCEPCIONAL pelo Contran, com motivo comprovado e avaliação de segurança.'],atencao=['Não ensinar todo recall com bloqueio imediato e sem exceção.','Não dispensar inspeção específica nem criar calendário geral ativo a partir de resolução suspensa.','Distinguir débito exigível, defesa, certificado de registro e certificado anual.'],sources=[L2021,L2023,STF,D170])
add(132,'Um veículo novo segue da fábrica ao município de destino nos termos do Contran. Resposta: a dispensa de licenciamento vale para esse trajeto regulado.', 'Após chegar, o veículo não ganha isenção indefinida para passeios e uso habitual só porque é novo.', 'A dispensa cobre circulação habitual indefinida do veículo zero quilômetro? Não. O artigo limita a circulação regulada ao trajeto entre fábrica e município de destino.', 'O recorte também contempla importados? Sim. O §1º prevê trajeto entre alfândega/entreposto alfandegário e município de destino.', 'Trajeto de destino','Percurso delimitado da dispensa, sem exoneração permanente do licenciamento.',notes=['§2º revogado não cria nova dispensa. O exemplo de carga em caminhão cegonha não substitui a análise da circulação própria do veículo.'])
add(133,'Na fiscalização, o agente acessa o sistema devido e verifica o licenciamento. Resposta: o porte do certificado é dispensado pelo parágrafo.', 'Sem possibilidade de consulta naquele momento, não invocar a exceção apenas porque um sistema existe em tese.', 'A simples existência abstrata de banco informatizado dispensa sempre o porte? Não. Deve ser possível acessar o devido sistema no momento da fiscalização para verificar o licenciamento.', 'A dispensa do porte elimina a obrigação de licenciar o veículo? Não. Refere-se à apresentação/porte do documento, não à regularidade anual.', 'Porte dispensado','Exceção de apresentação quando a fiscalização consegue verificar a regularidade.',notes=['Distinguir porte documental e licenciamento efetivo; dispensa não regulariza veículo.'])
add(134,'O comprador não providencia novo CRV no prazo de trinta dias. Resposta: o vendedor deve observar a comunicação no prazo de sessenta dias previsto após esse marco, evitando a responsabilidade pelas penalidades e reincidências até comunicar.', 'O comprovante eletrônico com assinatura válida pode substituir o autenticado nos termos do regulamento; mensagem informal não basta automaticamente.', 'O prazo de trinta dias do comprador é o mesmo dever de sessenta dias do vendedor? Não. São sujeitos e marcos distintos nos arts. 123 e 134; não trocar os prazos.', 'A solidariedade textual do art. 134 abrange automaticamente toda indenização civil e todo IPVA? Não. O artigo trata de penalidades e reincidências; outros efeitos têm regimes e jurisprudência próprios.', 'Comunicação da venda','Dever do antigo proprietário no recorte legal, diferente de transferir o registro pelo comprador.',notes=['Não generalizar solidariedade de penalidades para danos civis ou todo tributo. A comunicação não é declaração de culpa penal por conduta alheia.'],sources=[L2020])
add('134-a','Uma bicicleta elétrica atende ao enquadramento de pedal assistido, potência e velocidade da Resolução 996. Resposta: integra a dispensa de registro, licenciamento e emplacamento do art. 12 da resolução.', 'Veículo elétrico comercialmente chamado de bicicleta, mas enquadrado como ciclomotor, não recebe a mesma dispensa apenas pelo nome.', 'Toda bicicleta ou veículo elétrico com acelerador é automaticamente isento de registro? Não. Conferir a classe e características técnicas; bicicleta elétrica regulamentar não é sinônimo de qualquer elétrico.', 'A transição do art. 14 da Resolução 996 ainda permite circulação indefinida de ciclomotor antigo sem regularizar em 2026? Não. O prazo ali previsto terminou em 31/12/2025; não tratá-lo como futuro na conferência de 13/10/2026.', 'Enquadramento elétrico','Classificação técnica que define dispensa ou exigências, distinta do nome comercial.',extra_points=['Resolução 996 vigente desde 3/7/2023: bicicleta elétrica ordinária com pedal assistido, sem acelerador, motor até 1000 W e propulsão auxiliar até 32 km/h, com hipóteses específicas.','Art. 12: bicicleta elétrica/equipamento autopropelido não sujeitos a registro/licenciamento/emplacamento; ciclomotor tem outro regime.'],notes=['A classificação de equipamento autopropelido pode ter acelerador; não concluir que todo veículo com acelerador é necessariamente ciclomotor.','Não afirmar prorrogação da transição até data não verificada; índice consultado mantém o ato sem indicação de alteração desse prazo.'],sources=[R996])
add(135,'Um táxi pretende registro e emplacamento comercial. Resposta: necessita autorização do poder público competente para o serviço abrangido.', 'A regra para categoria de aluguel não deve ser generalizada automaticamente a todo veículo particular que se relaciona a uma atividade econômica; conferir enquadramento e regime específico.', 'Cumprir registro e licenciamento dispensa autorização do serviço no recorte deste artigo? Não. O caput exige estar devidamente autorizado pelo poder público concedente.', 'A autorização concede liberdade para ignorar requisitos técnicos do CTB? Não. Integra os deveres, sem afastar segurança, registro ou licenciamento pertinentes.', 'Autorização do serviço','Ato do poder competente para exploração, distinto da regularidade técnica do veículo.',notes=['Não generalizar regras de táxi para todo transporte por aplicativo sem verificar sua disciplina própria.'])
add(136,'Um veículo escolar tem carroçaria amarela. Resposta: as cores da faixa/dístico são invertidas, conforme inciso III; não repetir amarelo sobre amarelo.', 'A autorização é estadual/distrital, mas competência municipal complementar continua pelo art. 139.', 'A inspeção legal do escolar é apenas anual? Não. O inciso II prevê semestral para equipamentos obrigatórios e de segurança, distinta do programa geral de inspeção.', 'Os cintos podem existir apenas para parte da lotação? Não. O inciso VI exige número igual à lotação, além dos demais equipamentos.', 'Identificação escolar','Faixa e dístico nos requisitos legais, com inversão de cores para carroçaria amarela.',extra_points=['Faixa de 40 cm à meia altura, em toda extensão lateral/traseira; carroçaria amarela: INVERTER cores.','Lanternas superiores: dianteira branca fosca ou amarela e traseira vermelha, no recorte do inciso V.'],notes=['Não usar suspensão do programa de inspeção geral como dispensa da inspeção escolar específica.'])
add(137,'Uma van escolar autorizada pretende levar crianças acima da capacidade do fabricante. Resposta: a autorização não permite excesso, mesmo se fisicamente couberem.', 'Além de respeitar capacidade, a autorização deve estar dentro do veículo, visível e com inscrição da lotação permitida.', 'Crianças pequenas podem superar o número autorizado por ocuparem menos espaço? Não. O artigo veda escolares em número superior à capacidade estabelecida pelo fabricante.', 'Guardar a autorização em casa satisfaz a exigência do art. 137? Não. Deve ser afixada na parte interna, em local visível e com inscrição da lotação.', 'Lotação escolar','Limite que não aumenta por tamanho ou acomodação improvisada de crianças.',notes=['Autorização e capacidade não dispensam cintos em número igual à lotação.'])
add(138,'Uma motorista de 25 anos, categoria D e curso especializado tem uma única gravíssima nos últimos doze meses. Resposta: o inciso IV atual não exige zero gravíssima, mas não ter cometido MAIS DE UMA, mantendo os demais requisitos.', 'Ter duas gravíssimas nesse intervalo viola esse requisito; categoria B não substitui D por dirigir uma van pequena.', 'O inciso IV atual proíbe qualquer infração grave ou média no período? Não. A redação da Lei 14.071/2020 trata de mais de uma gravíssima nos doze últimos meses.', 'Curso especializado hoje deve ser estudado exclusivamente pela Resolução 789/2020? Não. A Resolução 1020/2025 revogou a 789 e disciplina formação especializada, incluindo transporte de escolares.', 'Requisito de histórico','Condição legal de gravíssimas no período, sem recuperar o rol antigo de infrações.',notes=['Texto do inciso I: idade SUPERIOR a vinte e um anos; não reescrever silenciosamente a expressão legal.','Resolução 1020/2025, publicada/vigente em 9/12/2025, inclui escolares no art. 67 e formação especializada nos seguintes. Não certifica aqui toda carga horária de normativo Senatran.'],sources=[L2020,R1020])
add(139,'O município aplica requisitos próprios de transporte escolar em sua circunscrição. Resposta: o capítulo não exclui essa competência.', 'A regra complementar não autoriza eliminar a inspeção semestral ou aceitar condutor sem categoria exigida pelo CTB.', 'A autorização estadual elimina toda exigência municipal de escolar? Não. O art. 139 preserva a aplicação das exigências previstas em regulamentos municipais.', 'A competência municipal permite contrariar requisitos federais do capítulo? Não. Deve ser exercida em integração ao CTB, sem transformar complementaridade em dispensa dos deveres nacionais.', 'Competência complementar','Atuação local preservada, compatível com os deveres nacionais.',notes=['Evitar afirmar exclusividade estadual da regulamentação de escolares.'])
add('139-a','Em outubro de 2026, um motofretista alega dispensa de categoria de aluguel e de inspeção semestral com base na MP 1360. Resposta: a MP teve vigência encerrada em 15/9/2026; não usar suas revogações temporárias como regra vigente de dispensa, e conferir requisitos restaurados no compilado.', 'Relações constituídas durante a vigência da MP exigem análise de transição do art. 62 da Constituição; não aplicar a regra de outubro indistintamente a todo período anterior.', 'Vigência encerrada junto à anotação da MP significa que os incisos originais I e IV continuam revogados para sempre? Não. O ato congressual encerra a vigência da MP; no compilado atual os requisitos originais reaparecem e a revogação temporária é histórica.', 'A exceção para gás de cozinha e água mineral permite transporte livre na motocicleta? Não. O §2º exige auxílio de side-car e observância da regulamentação, sem liberar todo inflamável.', 'Caducidade da MP','Fim da eficácia da medida provisória, com retorno ao regime aplicável e análise específica das relações temporais.',simples='Motofrete exige autorização estadual/distrital e os requisitos do art. 139-A, incluindo categoria de aluguel, mata-cachorro, antena corta-pipas e inspeção semestral. ATUALIZAÇÃO: a MP 1360/2026 flexibilizou autorização e revogou temporariamente os incisos I e IV, mas teve vigência ENCERRADA em 15/9/2026 pelo Ato Declaratório 96/2026. Em 13/10/2026, não ensinar a dispensa temporária como atual. Relações do período da MP exigem análise própria do art. 62 da Constituição. Cargas seguem regulamento; gás de cozinha/água mineral são exceções com side-car.',pontos=['Autorização estadual/distrital e categoria de ALUGUEL no regime atual.','Mata-cachorro e antena corta-pipas conforme regulamento.','Inspeção SEMESTRAL: não tratar revogação temporária da MP como permanente.','MP de 19/5/2026: prazo encerrado em 15/9/2026; ato de 16/9 publicado em 17/9.','Inflamáveis/tóxicos/combustíveis: proibição com exceção de gás de cozinha e galões de água mineral mediante side-car.'],atencao=['A marcação vigência encerrada refere-se à MP, não a uma revogação permanente dos requisitos originais.','Distinguir regra atual e relações constituídas durante a MP conforme CF 62, §§3º/11; não certificada aqui existência ou alcance de todo decreto legislativo de transição.','Formação especializada: Resolução 1020/2025 revogou 930/2022; não citar esta como regulamento atual sem ressalva.'],sources=[MP1360,ADC96,CF,R1020])
add('139-b','Um município estabelece requisitos adicionais válidos para motofrete em suas vias. Resposta: a competência municipal e estadual é preservada no âmbito da respectiva circunscrição.', 'O órgão não pode usar complementaridade para ignorar a vigência encerrada da MP ou eliminar indistintamente o regime nacional.', 'O capítulo torna a regulamentação de motofrete exclusivamente federal? Não. O artigo preserva exigências previstas nos regulamentos municipais ou estaduais.', 'A norma local vale automaticamente fora da circunscrição da autoridade? Não. O caput delimita atuação ao âmbito das respectivas circunscrições.', 'Circunscrição do motofrete','Limite territorial e de competência para exigências locais compatíveis.',notes=['Integrar art. 139-A e a caducidade da MP 1360 em setembro/2026; preservação local não resolve toda transição.'],sources=[ADC96])
assert len(rows)==50 and set(rows)==set(expected)
for key,row in rows.items():
 assert 'Variação:' in row['exemplo'] and len(row['prova'])==2,key
 assert all('?' in q and len(q.split('?',1)[1].strip())>45 for q in row['prova']),key
 assert row['termos'] and all(t['significado'] for t in row['termos'])
Path(sys.argv[2]).write_text(json.dumps({'course_slug':'transito','units':rows},ensure_ascii=False,indent=2)+'\n')
print('50 explicitly reviewed CTB units')
